begin;
create table public.asset_theses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id)on delete cascade,asset_id uuid not null references public.assets(id),version text not null,status text not null check(status in('ACTIVE','INVALIDATED','RETIRED')),thesis text not null,causal_drivers jsonb not null,assumptions jsonb not null,catalysts jsonb not null,counter_thesis text not null,invalidators jsonb not null,review_on date not null,evidence_status text not null check(evidence_status in('HYPOTHESIS','SHADOW','VALIDATED')),created_at timestamptz not null default now(),unique(user_id,asset_id,version));
create table public.valuation_snapshots(id uuid primary key default gen_random_uuid(),asset_id uuid not null references public.assets(id),calculated_at timestamptz not null,methodology_version text not null,fair_value_low numeric not null,fair_value_base numeric not null,fair_value_high numeric not null,current_price numeric not null,components jsonb not null,input_observation_ids uuid[]not null,evidence_status text not null check(evidence_status in('HYPOTHESIS','SHADOW','VALIDATED')),warnings jsonb not null default'[]',unique(asset_id,calculated_at,methodology_version),check(fair_value_low<=fair_value_base and fair_value_base<=fair_value_high));
create table public.scenario_sets(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id)on delete cascade,asset_id uuid not null references public.assets(id),version text not null,horizon_months integer not null check(horizon_months>0),scenarios jsonb not null,expected_return_percent numeric,downside_percent numeric,upside_downside_ratio numeric,evidence_status text not null check(evidence_status in('HYPOTHESIS','SHADOW','VALIDATED')),created_at timestamptz not null default now(),unique(user_id,asset_id,version));
create table public.allocation_recommendations(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id)on delete cascade,calculated_at timestamptz not null,mandate_id uuid not null references public.investor_mandates(id),portfolio_snapshot_id uuid references public.portfolio_snapshots(id),decision_snapshot_ids uuid[]not null,valuation_snapshot_ids uuid[]not null,scenario_set_ids uuid[]not null,allocation_policy_version text not null,risk_policy_version text not null,status text not null check(status in('AVAILABLE','FROZEN','NO_FEASIBLE_ALLOCATION')),evidence_status text not null default'SHADOW'check(evidence_status='SHADOW'),target_ranges jsonb not null,binding_constraints jsonb not null,warnings jsonb not null,explanation_facts jsonb not null,unique(user_id,calculated_at,allocation_policy_version));
create table public.analyst_signoffs(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id)on delete cascade,recommendation_id uuid not null references public.allocation_recommendations(id),action text not null check(action in('APPROVE','MODIFY','REJECT','DEFER')),rationale text not null,modified_targets jsonb,review_on date,created_at timestamptz not null default now());
create table public.catalyst_events(id uuid primary key default gen_random_uuid(),user_id uuid references auth.users(id)on delete cascade,asset_id uuid references public.assets(id),event_type text not null,title text not null,event_at timestamptz not null,source_url text,thesis_id uuid references public.asset_theses(id),status text not null default'SCHEDULED'check(status in('SCHEDULED','OCCURRED','CANCELLED')),created_at timestamptz not null default now());
do $$declare t text;begin foreach t in array array['asset_theses','valuation_snapshots','scenario_sets','allocation_recommendations','analyst_signoffs','catalyst_events']loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy "users own theses"on public.asset_theses for all to authenticated using((select auth.uid())=user_id)with check((select auth.uid())=user_id);create policy "authenticated read valuations"on public.valuation_snapshots for select to authenticated using(true);create policy "users own scenarios"on public.scenario_sets for all to authenticated using((select auth.uid())=user_id)with check((select auth.uid())=user_id);create policy "users read own recommendations"on public.allocation_recommendations for select to authenticated using((select auth.uid())=user_id);create policy "users own signoffs"on public.analyst_signoffs for all to authenticated using((select auth.uid())=user_id)with check((select auth.uid())=user_id);create policy "users own catalysts"on public.catalyst_events for all to authenticated using(user_id is null or(select auth.uid())=user_id)with check((select auth.uid())=user_id);
create trigger valuation_snapshots_immutable before update or delete on public.valuation_snapshots for each row execute function public.prevent_observation_mutation();create trigger allocation_recommendations_immutable before update or delete on public.allocation_recommendations for each row execute function public.prevent_observation_mutation();
insert into public.methodology_versions(methodology_type,code,version,status,rationale,configuration,expected_effect,evidence)values('ALLOCATION','BTC_ETH_CASH','allocation-policy-v1-shadow.1','SHADOW','Deterministic target ranges constrained by mandate, thesis, approved data, valuation and independent stress.','{"assets":["BTC","ETH","CASH"],"rangeWidthPercent":5,"stressIndependent":true,"humanApprovalRequired":true}','Produces auditable shadow target ranges; no execution.','{"validation":"UNVALIDATED"}'),('RISK','PORTFOLIO_LIMITS','risk-policy-v1-shadow.1','SHADOW','Hard mandate constraints and fail-closed freezes.','{"constraints":["cashFloor","assetCap","sourceApproval","thesisRequired","freeze"]}','Prevents exposure increases when evidence or operations are insufficient.','{"validation":"UNVALIDATED"}');
commit;
